/* ----- Notification du Système (remplace la carte dorée) ----- */
function sysNote(title, text, src) {
  let el = $('#gem'); if (!el) { el = document.createElement('div'); el.id = 'gem'; el.setAttribute('role', 'status'); document.body.appendChild(el); }
  el.className = 'gem snote';
  el.innerHTML = `<div class="sw"><i class="sw-c sw-tl"></i><i class="sw-c sw-tr"></i><i class="sw-c sw-bl"></i><i class="sw-c sw-br"></i><header class="sw-h"><span class="sw-dot"></span>NOTIFICATION</header><div class="sw-b"><p class="sn-t">${title}</p><p class="sn-q">${text}</p>${src ? `<p class="sn-s">${src}</p>` : ''}</div></div>`;
  el.classList.remove('on'); void el.offsetWidth; el.classList.add('on');
  clearTimeout(el._t); el._t = setTimeout(() => el.classList.remove('on'), 5200);
  el.onclick = () => el.classList.remove('on');
}

