/* ----- Succès du Système (onglet Trophées en thème Système) ----- */
function questCount() { return Object.values(sysS().q || {}).filter(q => q && q.done).length; }
function penPurged() { return Object.values(sysS().q || {}).some(q => q && q.pen && q.pen.n >= 100); }
