  sysPop('OBJET RARE OBTENU', `<div class="tr-sh">${hexB(TRG[x.type] || 'orbite', true)}</div><p class="tr-n">${esc(x.t)}</p><p class="sys-li" style="text-align:center">Ajouté à ton inventaire.</p>`, 'RANGER', 'lvl');
