/* =====================================================================
   SYSTÈME v3.16 — Foi, Arabe, Argent, Qibla aux couleurs du Système
   ===================================================================== */
/* ----- Les prières : le journal de quête ----- */
const PQ = { open: null };
const PQ_IDS = ['fajr', 'dhuhr', 'asr', 'maghrib', 'isha'];
function prayerQuest(k, d) {
  const isT = k === todayISO(), now = new Date(), t = ptDay(k), ids = PQ_IDS.filter(id => S.faith.habits.some(h => h.id === id));
  const done = ids.filter(id => { const v = pv(d[id]); return v && v !== 'x'; }).length;
  const LOCKI = `<svg viewBox="0 0 24 24" width="12" height="12" aria-hidden="true">${GLYPH.lock}</svg>`;
  const rows = ids.map(id => {
    const v = pv(d[id]), [s, e] = t.win[id], p = PRAYERS.find(q => q[0] === id);
    let st, cls, acts = false;
    if (v && v !== 'x') { st = `VALIDÉE · ${PWAY[v][0]} · +${prayerPts(id, v)} XP`; cls = 'ok'; }
    else if (v === 'x') { st = 'MANQUÉE'; cls = 'ko'; }
    else if (isT && s > now) { st = `VERROUILLÉE · s'ouvre à ${hm(s)}`; cls = 'lk'; }
    else if (isT && e > now) { st = `EN COURS · fin dans ${leftTxt(e - now)}`; cls = 'cur'; acts = true; }
    else { st = 'TEMPS ÉCOULÉ · à valider'; cls = 'exp'; acts = true; }
    const open = cls !== 'lk' && (acts || PQ.open === id);
    const ways = ['m', 'g', 's', 'r'].concat(cls === 'cur' ? [] : ['x']);
    return `<div class="pq ${cls}"><button class="pq-h" data-pqo="${id}" ${cls === 'lk' ? 'disabled' : ''} aria-expanded="${open}">
        <span class="sys-box">${cls === 'ok' ? '✓' : cls === 'ko' ? '✕' : cls === 'lk' ? LOCKI : ''}</span>
        <span class="grow"><b>${PNAMES[id].toUpperCase()}</b><span class="ar" lang="ar">${p[2]}</span><small>${st}</small></span>
        <span class="pq-t num">${hm(s)}<i>${hm(e)}</i></span></button>
      ${open ? `<div class="pq-a">${ways.map(w => `<button data-pway="${w}" data-pid="${id}" aria-pressed="${v === w}">${PICON(w, 16)}<span>${PSHORT[w] || PWAY[w][0]}</span></button>`).join('')}${v ? `<button class="pq-x" data-pway="" data-pid="${id}">Effacer</button>` : ''}</div>` : ''}</div>`;
  }).join('');
  const cur = ids.find(id => { const [s, e] = t.win[id]; return isT && s <= now && e > now; });
  return sysWin(`QUÊTE · LES CINQ PRIÈRES [${done}/${ids.length}]`, `<p class="sys-qt">${isT ? (cur ? `${PNAMES[cur].toUpperCase()} EST OUVERTE` : done === ids.length ? 'QUÊTE ACCOMPLIE' : 'LA PROCHAINE PORTE S\'OUVRIRA À SON HEURE') : DAY_LONG.format(parseDate(k)).toUpperCase()}</p>${rows}
`, done === ids.length ? 'done' : '');
}
function pqClick(t) {
  const el = t.closest('[data-pqo]'); if (!el) return false;
  PQ.open = PQ.open === el.dataset.pqo ? null : el.dataset.pqo; const y = window.scrollY; render(); window.scrollTo(0, y); return true;
}

/* ----- L'arabe : l'arbre de compétences et la grille de runes ----- */
const ARSK = ['Lexique', 'Exégèse', 'Formules', 'Vocalisation', 'Lecture'];
function arTree() {
  const cur = AR.p || Math.min(5, arPalier());
  const nodes = ARP.map(([t, s], i) => {
    const n = i + 1, op = arOpen(n), dn = arDone(n), [x, y] = arProg(n), pc = y ? x / y : 0;
    return `<button class="atn ${dn ? 'ok' : ''} ${op ? '' : 'lk'} ${cur === n ? 'cur' : ''}" data-arp="${n}" ${op ? '' : 'disabled'}>
      <span class="atn-hex"><svg viewBox="-27 -27 54 54" aria-hidden="true"><polygon points="0,-24 21,-12 21,12 0,24 -21,12 -21,-12" class="sx-hex"/></svg><b>${dn ? '✓' : op ? ['I', 'II', 'III', 'IV', 'V'][i] : '✕'}</b></span>
      <span class="grow"><small>COMPÉTENCE ${['I', 'II', 'III', 'IV', 'V'][i]} · ${ARSK[i].toUpperCase()}</small><b>${t}</b><em>${op ? s : 'Verrouillée · termine la compétence précédente'}</em>
        ${op ? `<span class="atn-bar"><i style="width:${(pc * 100).toFixed(0)}%"></i></span><span class="atn-n num">${dn ? 'MAÎTRISÉE' : `${x} / ${y}`}</span>` : ''}</span></button>`;
  }).join('<i class="atn-link" aria-hidden="true"></i>');
  return sysWin(`ARBRE DE COMPÉTENCES · ARABE [${arCount()}/5]`, `<div class="atree">${nodes}</div><p class="sys-li" style="margin-top:8px;text-align:center">Chaque compétence maîtrisée débloque la suivante. Au bout : mémoriser le Coran.</p>`);
}
function runeCells() {
  return WORDS.map((w, i) => { const sc = Math.min(3, S.words[i] || 0); return `<button class="rune r${sc}" data-star="${i}" aria-label="${esc(w[1])}, ${sc} sur 3"><span lang="ar">${w[0]}</span></button>`; }).join('');
}
function runeGrid() {
  return sysWin(`GRIMOIRE DES RUNES · ${wordsKnown()}/${WORDS.length}`, `<p class="sys-qt">UNE RUNE PAR MOT DU CORAN · ALLUMÉE À 3 BONNES RÉPONSES</p><div class="runes" id="runes">${runeCells()}</div><p class="constel-tip" id="ctip"></p>`);
}

/* ----- L'argent : ressources, coffre et missions ----- */
function budgetHud(b, isCur) {
  const today = todayISO(), spentT = b.exps.filter(t => t.date === today).reduce((a, t) => a + numv(t.amount), 0);
  const ration = isCur && b.daysLeft ? Math.max(0, (b.reste + spentT) / b.daysLeft) : 0, leftT = ration - spentT;
  const pR = b.free > 0 ? Math.max(0, Math.min(1, b.reste / b.free)) : 0, pT = ration > 0 ? Math.max(0, Math.min(1, leftT / ration)) : 0;
  const segs = n => Array.from({ length: 20 }, (_, i) => `<i class="${i < Math.round(n * 20) ? 'on' : ''}"></i>`).join('');
  return sysWin('RESSOURCES', `${isCur ? `<div class="rs-top"><div><p class="sys-k">RATION DU JOUR</p><p class="rs-big num ${leftT < 0 ? 'neg' : ''}">${eur0(leftT)}</p></div><p class="rs-side num">sur ${eur0(ration)}<br>dépensé ${eur0(spentT)}</p></div>
      <div class="rs-g ${leftT < 0 ? 'neg' : pT < .25 ? 'low' : ''}">${segs(pT)}</div>` : ''}
    <div class="sys-row" style="margin-top:14px"><span><b class="sys-k">RÉSERVE DU MOIS</b></span><span class="num ${b.reste < 0 ? 'neg' : ''}">${eur0(b.reste)} / ${eur0(b.free)}</span></div>
    <div class="sys-xp"><i style="width:${(pR * 100).toFixed(1)}%"></i></div>
    <p class="sys-xpt">${isCur ? `${b.daysLeft} jour${b.daysLeft > 1 ? 's' : ''} restant${b.daysLeft > 1 ? 's' : ''} · la ration se recalcule à chaque dépense` : monthLabel(A.month)}</p>`, b.reste < 0 ? 'pen' : '');
}
function hoursHud() {
  const ym = todayISO().slice(0, 7), st = S.settings;
  const rows = Object.keys(EMP).map(k => { const t = sumShifts(shiftsIn(ym, k)), base = numv(st.base[k]) * 60 || (k === 'pizza' ? 4800 : 9000), p = Math.min(1, t.worked / base);
    return `<div class="hm-r"><div class="sys-row" style="margin:0"><span><span class="edot ${k}"></span> <b>${EMP[k].toUpperCase()}</b></span><span class="num">${fmtH(t.worked)} / ${Math.round(base / 60)} h</span></div>
      <div class="sys-xp ${k}"><i style="width:${(p * 100).toFixed(1)}%"></i></div><p class="sys-xpt">${t.n} service${t.n > 1 ? 's' : ''} · ${Math.round(p * 100)} %${t.night ? ` · nuit ${fmtH(t.night)}` : ''}</p></div>`; }).join('');
  const tot = sumShifts(shiftsIn(ym));
  return sysWin(`MISSIONS · ${monthLabel(ym).toUpperCase()}`, `<div class="hm-tot"><p class="sys-k">HEURES ACCOMPLIES</p><p class="rs-big num">${fmtH(tot.worked)}</p></div>${rows}`);
}

/* ----- La Qibla : le marqueur de quête. À travers la caméra, comme dans un jeu en monde ouvert :
   un losange de quête flotte dans la vraie pièce, dans la direction de la Kaaba, avec sa distance ;
   une traînée lumineuse au sol y mène. Hors champ, le marqueur se colle au bord de l'écran.
   Aligné : il se verrouille et une fenêtre du Système s'affiche. Sans caméra : fond noir du Système. ----- */
