    <div class="root">${w[2] ? `racine <bdi class="ar" lang="ar">${w[2]}</bdi>` : 'mot-outil'}&ensp;<button class="say" data-say="${w[0]}" aria-label="Écouter la prononciation">${SPK} Écouter</button></div>
