const FOI_W = [['coran', .24], ['hadith', .18], ['recit', .2], ['savant', .14], ['fait', .1], ['poeme', .07], ['obs', .07]];
function foiType() { let r = Math.random(); for (const [t, w] of FOI_W) { if ((r -= w) < 0) return t; } return 'coran'; }
