  const id = el.dataset.fid, r = srcRar(id), c = fxCardOf(el), n = SRC_IDS.indexOf(id);
  el.classList.add('r-' + r[0]); el.dataset.rar = r[0];
  const lbl = c && FXC[c.t] ? FXC[c.t].lbl : '';
