  if (q) q.innerHTML = `<span class="sys-k">QUÊTE · 5 FRAGMENTS</span><span class="src-seg">${[0, 1, 2, 3, 4].map(k => `<i class="${k < n ? 'on' : ''}"></i>`).join('')}</span><b class="num">${n}/5</b>`;
