      if (gain) { nourAdd(gain); day.xp += gain; FXS.sx += gain; save(); const st = $('#feed').getBoundingClientRect(); lastPt = { x: innerWidth / 2, y: st.top + st.height * .45 }; burst(r[0] === 'legendaire' ? 30 : r[0] === 'epique' ? 18 : 8, `+${gain} XP`, r[0] !== 'commun'); }
      if (r[0] === 'legendaire' && !(S.flux.leg || []).includes(id)) { S.flux.leg = (S.flux.leg || []).concat(id); save(); sysNote('Fragment légendaire découvert', `${FXC[(fxCardOf(el) || {}).t] ? FXC[fxCardOf(el).t].lbl : ''} · Fragment #${String(SRC_IDS.indexOf(id) + 1).padStart(4, '0')}`); sfx('big'); }
