  if ((el = c('[data-ar2q]'))) { const it = AR.q.list[AR.q.i], k = Number(el.dataset.ar2q); AR.q.pick = k; if (it.opts[k] === it[1]) { AR.q.score++; try { navigator.vibrate && navigator.vibrate(8); } catch (e) {} } rr(); return true; }
