(function intro() {
  const el = document.getElementById('intro'); if (!el) return;
  let sysI = true; try { sysI = (localStorage.getItem('sdp-ui') || 'systeme') === 'systeme'; } catch (e) {}
  const done = () => { if (el.parentNode) el.remove(); };
  let awake = true; try { awake = localStorage.getItem('sdp-awake') === '1'; } catch (e) {}
  if (sysI && !awake) { el.classList.add('sys-i'); awakeIntro(el, done); return; }
  if (sysI) {
    /* Reconnexion : l'écran attend un toucher (le son ne peut démarrer qu'après un geste), puis la connexion se joue avec ses sons. */
    el.classList.add('sys-i', 'wait'); el.innerHTML = sysIntro() + '<p class="sb-gate">TOUCHE POUR TE CONNECTER</p>';
    let started = false;
    const start = sound => { if (started) return; started = true; el.classList.remove('wait');
      if (sound) { try { audioUnlock(); sfx('boot'); [200, 1000, 1700, 2000, 2400].forEach(d => setTimeout(() => { try { sfx('line'); } catch (e) {} }, d)); setTimeout(() => sfx('win'), 2600); } catch (e) {} }
      setTimeout(done, 4300); };
    el.addEventListener('click', () => { if (!started) start(true); else { el.classList.add('skip'); setTimeout(done, 320); } });
    setTimeout(() => start(false), 5000);
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) done();
    return;
  }
  el.addEventListener('click', () => { el.classList.add('skip'); setTimeout(done, 320); });
  el.addEventListener('animationend', e => { if (e.animationName === 'iout') done(); });
  setTimeout(done, sysI ? 4300 : 6800);
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) done();
})();
(async function boot() {
  S = await loadState();
  try { localStorage.setItem('sdp-ui', S.ui || 'systeme'); } catch (e) {}
  save(true);
  let t = location.hash.slice(1);
  if (t === 'arabe' || t === 'habitudes' || t === 'dhikr' || t === 'coeur' || t === 'nafila' || t === 'coran') { setFView(t); t = 'foi'; }
  if (t === 'heures' || t === 'budget' || t === 'zakat') { setAView(t); t = 'argent'; }
  if (CVIEWS.includes(t)) { setCView(t); t = 'corps'; }
  if (!TABS.includes(t)) { try { t = localStorage.getItem('sdp-tab'); } catch (e) {} }
  if (t === 'flux' || t === 'z') t = 'orbite';
  if (t === 'heures' || t === 'budget' || t === 'zakat') { setAView(t); t = 'argent'; }
  tab = TABS.includes(t) ? t : 'orbite';
  render(true);
  if ('serviceWorker' in navigator && location.protocol !== 'file:') {
    navigator.serviceWorker.register('sw.js').then(reg => {
      /* Mise à jour : proposée dès qu'une nouvelle version attend (même téléchargée lors d'une ouverture précédente),
         et vérifiée à chaque retour dans l'app. Le bouton reste affiché 10 minutes. */
      const offer = w => { if (w && navigator.serviceWorker.controller) toast('Nouvelle version disponible', 'Recharger', () => w.postMessage('skipWaiting'), 600000); };
      if (reg.waiting) offer(reg.waiting);
      reg.addEventListener('updatefound', () => {
        const nw = reg.installing;
        nw && nw.addEventListener('statechange', () => { if (nw.state === 'installed') offer(nw); });
      });
      document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') reg.update().catch(() => {}); });
    }).catch(() => {});
    let reloaded = false; const hadController = !!navigator.serviceWorker.controller;
    navigator.serviceWorker.addEventListener('controllerchange', () => { if (hadController && !reloaded) { reloaded = true; save(true); location.reload(); } });
  }
})();
